draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 40 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 40 - 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // speech bubble
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 20, 40, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Truth', W/2 + 80, H/2 - 20);

  // calmness wave
  ctx.beginPath();
  ctx.moveTo(0, H - 20 * Math.sin(3 * t));
  ctx.lineTo(W, H - 20 * Math.sin(3 * t + Math.PI));
  ctx.stroke();

  ctx.restore();
}
